export default function ActionList({ actions, uploaded, selectedActions, onActionClick, onApplySelected, isLoading }) {
  return (
    <div className="action-list">
      <div className="action-buttons">
        {actions.map((action) => (
          <button
            key={action}
            className={`action-btn ${selectedActions.includes(action) ? "active" : ""}`}
            onClick={() => onActionClick(action)}
            disabled={!uploaded || isLoading}
          >
            {action}
          </button>
        ))}
      </div>

      {/* ✅ Show Apply button only when something is selected */}
      {selectedActions.length > 0 && (
        <button
          className="apply-btn"
          onClick={onApplySelected}
          disabled={isLoading}
        >
          ⚡ Apply {selectedActions.length} Action{selectedActions.length > 1 ? "s" : ""}
        </button>
      )}
    </div>
  );
}
